from collections import deque

def get_3_regions(grid):
    """Get connected regions of 3s (4-connected)"""
    h, w = len(grid), len(grid[0])
    visited = [[False] * w for _ in range(h)]
    regions = []

    for i in range(h):
        for j in range(w):
            if grid[i][j] == 3 and not visited[i][j]:
                region = []
                queue = deque([(i, j)])
                visited[i][j] = True
                while queue:
                    ci, cj = queue.popleft()
                    region.append((ci, cj))
                    for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        ni, nj = ci + di, cj + dj
                        if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == 3 and not visited[ni][nj]:
                            visited[ni][nj] = True
                            queue.append((ni, nj))
                regions.append(region)
    return regions

